#!/bin/bash
# R36 Tuner Next.sh — self-extracting launcher for dArkOSRE.
# Extracts bundled tools on first run, then launches tuner_ui.

# Detach from EmulationStation's process group so systemctl stop ES
# doesn't kill this script (affects distros with KillMode=control-group).
if [ -z "$R36TUNER_DETACHED" ]; then
    export R36TUNER_DETACHED=1
    exec setsid "$0" "$@"
fi

SELF="$(readlink -f "$0")"
TUNER_VERSION="1.8"
TOOLS_STAMP="/usr/local/lib/.r36tuner_tools_ok_v${TUNER_VERSION}"

extract_bin() {
    local marker_start="$1" marker_end="$2" dest="$3"
    [ -x "$dest" ] && return 0
    echo "[r36tuner] extracting $(basename $dest)..."
    awk "/^# $marker_start$/{found=1;next} /^# $marker_end$/{exit} found{print}" "$SELF" \
        | base64 -d > /tmp/.r36_extract_$$
    echo ark | sudo -S mv /tmp/.r36_extract_$$ "$dest"
    echo ark | sudo -S chmod +x "$dest"
}

extract_bin_force() {
    local marker_start="$1" marker_end="$2" dest="$3"
    echo "[r36tuner] extracting $(basename $dest)..."
    awk "/^# $marker_start$/{found=1;next} /^# $marker_end$/{exit} found{print}" "$SELF" \
        | base64 -d > /tmp/.r36_extract_$$
    echo ark | sudo -S mkdir -p "$(dirname $dest)"
    echo ark | sudo -S mv /tmp/.r36_extract_$$ "$dest"
    echo ark | sudo -S chmod +x "$dest"
}

setup_glmark2_data() {
    [ -d /usr/local/share/glmark2data/shaders ] && return 0
    echo "[r36tuner] extracting glmark2 data (~6 MB)..."
    awk '/^# __GLMARK2_DATA_START__$/{found=1;next} /^# __GLMARK2_DATA_END__$/{exit} found{print}' "$SELF" \
        | base64 -d > /tmp/r36_glmark2data.deb
    echo ark | sudo -S bash -c '
        dpkg -x /tmp/r36_glmark2data.deb /tmp/r36_glmark2data_x
        mkdir -p /usr/local/share/glmark2data/shaders
        cp -rn /tmp/r36_glmark2data_x/usr/share/glmark2/models   /usr/local/share/glmark2data/ 2>/dev/null || true
        cp -rn /tmp/r36_glmark2data_x/usr/share/glmark2/textures  /usr/local/share/glmark2data/ 2>/dev/null || true
        cp     /tmp/r36_glmark2data_x/usr/share/glmark2/shaders/* /usr/local/share/glmark2data/shaders/
        sed -i "s/MEDIUMP_OR_DEFAULT/mediump/g; s/HIGHP_OR_DEFAULT/highp/g" /usr/local/share/glmark2data/shaders/*
        rm -rf /tmp/r36_glmark2data_x /tmp/r36_glmark2data.deb
    '
}

if [ ! -f "$TOOLS_STAMP" ]; then
    extract_bin_force __TUNER_UI_START__ __TUNER_UI_END__ /opt/system/tuner_ui
    extract_bin __FDTGET_START__  __FDTGET_END__  /usr/local/bin/fdtget
    extract_bin __FDTPUT_START__  __FDTPUT_END__  /usr/local/bin/fdtput
    extract_bin __CPUBENCH_START__ __CPUBENCH_END__ /usr/local/bin/r36_cpubench
    extract_bin __RAMBENCH_START__ __RAMBENCH_END__ /usr/local/bin/r36_rambench
    extract_bin __GLMARK2_BIN_START__ __GLMARK2_BIN_END__ /usr/local/bin/glmark2-es2-drm-legacy
    setup_glmark2_data
    echo ark | sudo -S touch "$TOOLS_STAMP"
fi

# SDL2 environment
# Point directly at the Mali blob so EGL works even if libEGL.so was overwritten by Mesa
export SDL_VIDEO_EGL_DRIVER=/lib/aarch64-linux-gnu/libmali-bifrost-g31-rxp0-gbm.so
export XDG_RUNTIME_DIR=/run/user/1000
export SDL_GAMECONTROLLERCONFIG_FILE=/opt/inttools/gamecontrollerdb.txt

# Auto-detect SDL video backend if not already set by the system
if [ -z "$SDL_VIDEODRIVER" ]; then
    if [ -e /dev/dri/card0 ]; then
        export SDL_VIDEODRIVER=kmsdrm
        export SDL_VIDEO_KMSDRM_DRM_DEVICE=/dev/dri/card0
    elif [ -e /dev/dri/card1 ]; then
        export SDL_VIDEODRIVER=kmsdrm
        export SDL_VIDEO_KMSDRM_DRM_DEVICE=/dev/dri/card1
    elif [ -e /dev/fb0 ]; then
        export SDL_VIDEODRIVER=fbdev
        export SDL_FBDEV=/dev/fb0
    fi
fi

LOG=/tmp/tuner_launch.log
: > "$LOG"
exec >> "$LOG" 2>&1

cleanup() {
    echo "[r36tuner] restarting EmulationStation..."
    echo ark | sudo -S systemctl start emulationstation 2>/dev/null || true
    echo ark | sudo -S rm -f /boot/.r36_dtb_patch_booting 2>/dev/null || true
}
trap cleanup EXIT SIGINT SIGTERM

echo "[r36tuner] stopping EmulationStation..."
echo ark | sudo -S systemctl stop emulationstation 2>/dev/null || true
echo ark | sudo -S pkill -9 -f /usr/bin/emulationstation/emulationstation 2>/dev/null || true
for i in $(seq 1 30); do
    pgrep -f /usr/bin/emulationstation/emulationstation > /dev/null 2>&1 || break
    sleep 0.1
done
sleep 0.3

TERM=linux clear > /dev/tty1 2>/dev/null || true
chvt 1 2>/dev/null || true

echo ark | sudo -S rm -f /boot/.r36_dtb_patch_booting 2>/dev/null || true

echo "[r36tuner] launching tuner_ui..."
/opt/system/tuner_ui
echo "[r36tuner] tuner_ui exited ($?)"
exit 0

